  voldown: "Volume down",
  volup: "Volume up",
};

function iconLabel(n) {
  var s = String(n)
    .replace(/^(mdi|custom):/, "")
    .replace(/[-_]+/g, " ");
  s = ICONNAMES[s] || s;
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function iconSvg(p) {
  return "<svg viewBox='0 0 24 24'><path fill='currentColor' stroke='none' d='" + p + "'/></svg>";
}

var ICONLIST = null,
  ICONPATH = {};

function iconPick(list, cur, fn, rec) {
  var wrap = mk("div", "idd"),
    items = [],
    view = [],
    shown = 0,
    io = null,
    q = "";
  var btn = mk("div", "sel selrow pane");
  function paintBtn() {
    btn.innerHTML =
      ic(cur && iconOk(cur) ? cur : "info") +
      "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='chev'>" +
      svg("chev") +
      "</span>";
    btn.querySelector(".nm").textContent = _T("icon");
    btn.querySelector(".sb").textContent = cur ? iconLabel(cur) : _T("choose_an_icon");
  }
  paintBtn();
  var panel = mk("div", "menu pane idd-panel");
  var sw = mk("div", "sqw pane", svg("search")),
    inp = mk("input", "sq");
  inp.type = "text";
  inp.placeholder = _T("search_icons");
  inp.setAttribute("autocomplete", "off");
  inp.setAttribute("autocapitalize", "off");
  sw.appendChild(inp);
  panel.appendChild(sw);
  var listEl = mk("div", "idd-list");
  panel.appendChild(listEl);
  var foot = mk("div", "idd-foot"),
    addBtn = mk("div", "idd-add");
  addBtn.textContent = _T("add_your_own_icon");
  addBtn.setAttribute("role", "button");
  foot.appendChild(addBtn);
  panel.appendChild(foot);
  /* An icon of the person's own is an SVG file: its paths are read, checked and kept as an icon named after the file. */
  addBtn.addEventListener("click", function () {
    pickTextFile({ accept: ".svg,image/svg+xml", maxBytes: 200 * 1024 }, function (text, fileName) {
      var r = iconFromSvg(text);
      if (r.problem) {
        toast(r.problem);
        return;
      }
      STORE.icons = STORE.icons || {};
      if (Object.keys(STORE.icons).length >= 300) {
        toast(_T("too_many_extra_icons_remove_some_fir"));
        return;
      }
      var nm = "custom:" + fileSlug(String(fileName || "").replace(/\.svg$/i, ""), "icon").slice(0, 24),
        base = nm,
        n = 1;
      while (STORE.icons[nm] && STORE.icons[nm] !== r.path) nm = base + "-" + ++n;
      STORE.icons[nm] = r.path;
      done(nm);
    });
  });
  function done(n) {
    cur = n;
    fn(n);
    if (!IC[n]) storeChanged();
    paintBtn();
    close();
  }
  function choose(n) {
    if (IC[n] || (STORE.icons && STORE.icons[n])) return done(n);
    iconFetchPath(n)
      .then(function (p) {
        STORE.icons = STORE.icons || {};
        if (Object.keys(STORE.icons).length >= 300) {
          toast(_T("too_many_extra_icons_remove_some_fir"));
          return;
        }
        STORE.icons[n] = p;
        done(n);
      })
      .catch(function () {
        toast(_T("couldn_t_load_that_icon"));
      });
  }
  function build() {
    var seen = {};
    items = [];
    function add(n, kw) {
      if (seen[n]) return;
      seen[n] = 1;
      items.push({ n: n, kw: kw || "" });
    }
    (rec || []).forEach(function (n) {
      add(n);
    });
    list.forEach(function (n) {
      add(n);
    });
    Object.keys(IC).forEach(function (n) {
      add(n);
    });
    Object.keys(STORE.icons || {}).forEach(function (n) {
      add(n);
    });
    (ICONLIST || []).forEach(function (x) {
      add("mdi:" + x.name, x.kw);
    });
    filter();
  }
  function filter() {
    var toks = q.toLowerCase().split(/\s+/).filter(Boolean);
    view = toks.length
      ? items.filter(function (it) {
          var h = it.n.toLowerCase() + " " + it.kw;
          return toks.every(function (k) {
            return h.indexOf(k) >= 0;
          });
        })
      : items;
    shown = 0;
    listEl.innerHTML = "";
    listEl.scrollTop = 0;
    if (!view.length) {
      var e = mk("div", "hint");
      e.textContent = _T("no_icons_found");
      listEl.appendChild(e);
    }
    more();
  }
  function more() {
    var end = Math.min(view.length, shown + 60),
      nrec = !q.trim() && rec ? rec.length : 0;
    for (var i = shown; i < end; i++) {
      /* The icons that fit what this is come first, under their own heading, then all of them. */
      if (nrec && i === 0) listEl.appendChild(mk("div", "idd-h")).textContent = _T("icons_suggested");
      if (nrec && i === nrec) listEl.appendChild(mk("div", "idd-h")).textContent = _T("icons_all");
      listEl.appendChild(row(view[i].n));
    }
    shown = end;
  }
  function row(n) {
    var r = mk("div", "idd-row" + (n === cur ? " on" : "")),
      p = (STORE.icons && STORE.icons[n]) || ICONPATH[n],
      g = mk("span", "ic", IC[n] ? svg(n) : p ? iconSvg(p) : svg("info")),
      l = mk("span", "idd-n");
    l.textContent = iconLabel(n);
    r.appendChild(g);
    r.appendChild(l);
    r.dataset.n = n;
    r.addEventListener("click", function () {
      choose(n);
    });
    if (!IC[n] && !p && io) io.observe(r);
    return r;
  }
  listEl.addEventListener("scroll", function () {
    if (listEl.scrollTop + listEl.clientHeight > listEl.scrollHeight - 160 && shown < view.length)
      more();
  });
  if (window.IntersectionObserver)
    io = new IntersectionObserver(
      function (es) {
        es.forEach(function (e) {
          if (!e.isIntersecting) return;
          io.unobserve(e.target);
          var n = e.target.dataset.n;
          iconPathQ(n)
            .then(function (p) {
              var g = e.target.querySelector(".ic");
              if (g) g.innerHTML = iconSvg(p);
            })
            .catch(function () {
              e.target.style.opacity = ".4";
            });
        });
      },
      { root: listEl }
    );
  inp.addEventListener("input", function () {
    q = inp.value;
    filter();
  });
  /* The panel floats over the page like the other dropdowns' menus; nothing under it moves. */
  function openIt() {
    closeMenu(true);
    /* The panel is reused: it comes back without the closing look it was given. */
    panel.classList.remove("out", "up");
    panel.style.display = "";
    placeMenu(panel, btn);
    build();
    iconListLoad(function () {
      if (MENU === panel) build();
    });
    setTimeout(function () {
      try {
        inp.focus();
      } catch (e) {}
    }, 60);
  }
  function close() {
    if (io) io.disconnect();
    if (MENU === panel) closeMenu();
  }
  btn.addEventListener("click", function () {
    if (btn._noopen) {
      btn._noopen = false;
      return;
    }
    openIt();
  });
  wrap.appendChild(btn);
  return wrap;
}

function cleanIcons(m) {
  var o = {};
  if (m && typeof m === "object")
    Object.keys(m)
      .slice(0, 300)
      .forEach(function (k) {
        if (ICON_RE.test(k) && pathOk(m[k])) o[k] = m[k];
      });
  return o;
}

/* Shared building blocks: pills, sliders, menus, dialogs, round buttons, tiles and rows, entity pickers, picture helpers. */

/* The page was scrolled at this moment (any scroll container). A touch that only stops a scroll, or that happens while the page scrolls, is not a tap. */
var SCROLLAT = 0;
document.addEventListener(
  "scroll",
  function () {
    SCROLLAT = Date.now();
  },
  true
);

/* A slider row. The row only reacts to a slide that is clearly horizontal: a finger that moves up or down is scrolling the page, and a touch that stops a scroll is not a tap. */
function attachSlide(el, h) {
  var sx = 0,
    sy = 0,
    t0 = 0,
    down = false,
    moved = false,
    scrolling = false,
    rect = null,
    tgt = null,
    held = false,
    timer = 0;
  function frac(e) {
    return Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
  }
  el.addEventListener("pointerdown", function (e) {
    down = true;
    moved = false;
    t0 = Date.now();
    /* The touch that stops a scrolling page is not meant for the row. */
    scrolling = t0 - SCROLLAT < 300;
    sx = e.clientX;
    sy = e.clientY;
    tgt = e.target;
    rect = el.getBoundingClientRect();
    dragging++;
    DRAGAT = Date.now();
    watchRelease(e.pointerId);
    capturePointer(el, e);
    held = false;
    clearTimeout(timer);
    if (h.onHold)
      timer = setTimeout(function () {
        if (down && !moved && !scrolling && SCROLLAT < t0 && !editing()) {
          held = true;
          h.onHold();
        }
      }, 450);
  });
  el.addEventListener("pointermove", function (e) {
    if (!down || held || scrolling) return;
    if (!moved) {
      var dx = Math.abs(e.clientX - sx),
        dy = Math.abs(e.clientY - sy);
      if (dy > 8 && dy >= dx) {
        scrolling = true;
        clearTimeout(timer);
        return;
      }
      if (dx > 10 && dx > 1.8 * dy) {
        moved = true;
        clearTimeout(timer);
      }
    }
    if (moved) h.onMove(frac(e));
  });
  /* The release is also heard on the window: when the finger lets go away from the row (or the row was replaced meanwhile) the row itself gets no pointerup, and a missing release would stop every refresh of the page. */
  function watchRelease(pid) {
    function fin(ev) {
      if (ev.pointerId !== pid) return;
      window.removeEventListener("pointerup", fin, true);
      window.removeEventListener("pointercancel", fin, true);
      if (ev.type === "pointerup") up(ev);
      else cancel();
    }
    window.addEventListener("pointerup", fin, true);
    window.addEventListener("pointercancel", fin, true);
  }
  function up(e) {
    if (!down) return;
    down = false;
    clearTimeout(timer);
    dragging = Math.max(0, dragging - 1);
    if (held) {
      held = false;
      if (h.onCancel) h.onCancel();
      return;
    }
    if (moved) h.onCommit(frac(e));
    else if (scrolling || SCROLLAT >= t0) {
      if (h.onCancel) h.onCancel();
    } else if (h.onTap) h.onTap(tgt);
  }
  function cancel() {
    if (down) {
      down = false;
      held = false;
      clearTimeout(timer);
      dragging = Math.max(0, dragging - 1);
      if (h.onCancel) h.onCancel();
    }
  }
  el.addEventListener("pointerup", up);
  el.addEventListener("pointercancel", cancel);
}

/* A popup's main action (Save, Done) stays pinned to the bottom of the popup instead of sitting after a long list. */
/* The press effect, for everything that can be pressed: one rule for all of it. The element shrinks (class pressed) while the finger is on it, for at least 110 ms so a quick tap shows it too, and it lets go as soon as the finger starts to drag or scroll. */
var PRESSABLE =
  ".pill:not(.static),.tile,.sel,.rnd,.rbtn,.opt,.rb-chip,.room,.qa,.swc,.tact,.camt,.dock .di,.menu .mi,.gb[role=button],.lp-it,.lp-bri-btn,.lp-style,.lp-mode,.lp-tile";
document.addEventListener(
  "pointerdown",
  function (e) {
    if (e.button || !e.target.closest) return;
    var el = e.target.closest(PRESSABLE);
    if (!el) return;
    var t0 = Date.now(),
      x = e.clientX,
      y = e.clientY;
    el.classList.add("pressed");
    function end() {
      document.removeEventListener("pointerup", end, true);
      document.removeEventListener("pointercancel", end, true);
      document.removeEventListener("pointermove", move, true);
      setTimeout(function () {
        el.classList.remove("pressed");
      }, Math.max(0, 110 - (Date.now() - t0)));
    }
    function move(ev) {
      if (Math.abs(ev.clientX - x) > 10 || Math.abs(ev.clientY - y) > 10) end();
    }
    document.addEventListener("pointerup", end, true);
    document.addEventListener("pointercancel", end, true);
    document.addEventListener("pointermove", move, true);
  },
  true
);

/* Calls fn when the element is pressed and held for 450 ms without moving. Returns a function that says whether the press that just ended was a hold, so the click after it can be ignored. */
function onHold(el, fn) {
  var timer = 0,
    sx = 0,
    sy = 0,
    fired = false;
  function stop() {
    clearTimeout(timer);
    timer = 0;
  }
  el.addEventListener("pointerdown", function (e) {
    if (e.button) return;
    fired = false;
    sx = e.clientX;
    sy = e.clientY;
    stop();
    timer = setTimeout(function () {
      timer = 0;
      if (editing()) return;
      fired = true;
      fn();
    }, 450);
  });
  el.addEventListener("pointermove", function (e) {
    if (timer && (Math.abs(e.clientX - sx) > 8 || Math.abs(e.clientY - sy) > 8)) stop();
  });
  ["pointerup", "pointercancel", "pointerleave"].forEach(function (ev) {
    el.addEventListener(ev, stop);
  });
  return function () {
    var was = fired;
    fired = false;
    return was;
  };
}

/* A locked lock unlocks by sliding its icon across its row, as on the old iPhone lock screen: drag the icon to the end; letting go
   before the end sends it back. A tap only nudges the icon to show which way to go. o.canSlide() says whether the slide applies now. */
function slideIcon(r, o, refresh) {
  var icn = r.querySelector(".ic"),
    fade = r.querySelectorAll(".tx,.vl"),
    from = 0,
    x = 0,
    drag = false,
    moved = false,
    reset = 0;
  function room() {
    return r.clientWidth - icn.offsetWidth - 16;
  }
  function place(v) {
    x = v;
    icn.style.transform = v ? "translateX(" + v + "px)" : "";
    var f = String(Math.max(0, 1 - v / (room() * 0.5)));
    for (var i = 0; i < fade.length; i++) fade[i].style.opacity = v ? f : "";
  }
  function back() {
    r.classList.add("easing");
    place(0);
  }
  r.slideReset = function () {
    clearTimeout(reset);
    if (x) back();
  };
  icn.addEventListener("pointerdown", function (e) {
    if (e.button || editing() || !o.canSlide()) return;
    clearTimeout(reset);
    r.classList.remove("easing");
    r.classList.add("sliding");
    from = e.clientX - x;
    drag = true;
    moved = false;
    capturePointer(icn, e);
  });
  icn.addEventListener("pointermove", function (e) {
    if (!drag) return;
    var v = Math.max(0, Math.min(room(), e.clientX - from));
    if (v > 6) moved = true;
    place(v);
  });
  function release() {
    if (!drag) return;
    drag = false;
    r.classList.remove("sliding");
    if (moved && x >= room() * 0.9) {
      o.slide();
      reset = setTimeout(back, 5000);
    } else back();
  }
  icn.addEventListener("pointerup", release);
  icn.addEventListener("pointercancel", release);
  icn.addEventListener(
    "click",
    function (e) {
      if (!o.canSlide() || editing()) return;
      e.stopPropagation();
      if (moved) return;
      r.classList.add("easing");
      place(18);
      setTimeout(back, 180);
    },
    true
  );
}

function pill(icon, name, o) {
  var r = mk("div", "pill pane" + (o.tap ? "" : " static") + (o.on ? " tg" : ""));
  r.dataset.i = icon;
  r.innerHTML =
    ic(icon) +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='vl'></span>";
  r.querySelector(".nm").textContent = name;
  var sb = r.querySelector(".sb"),
    vl = r.querySelector(".vl");
  if (o.pin) r.dataset.pin = JSON.stringify(o.pin);
  if (o.check) {
    r.classList.add("chk");
    r.setAttribute("role", "checkbox");
    r.appendChild(mk("span", "ck", svg("check")));
  }
  /* A row with an icon action opens its popup on a press and hold as well; the icon switches the device only on a tap. */
  var held = o.iconTap && o.tap ? onHold(r, o.tap) : null;
  if (o.tap)
    r.addEventListener("click", function (e) {
      if (held && held()) return;
      if (o.iconTap && e.target.closest(".ic")) {
        o.iconTap();
        return;
      }
      o.tap();
    });
  if (o.slide) slideIcon(r, o);
  var was = null;
  r.refresh = function () {
    if (o.slide) {
      var can = !!o.canSlide();
      r.classList.toggle("slidable", can);
      if (!can && r.slideReset) r.slideReset();
    }
    if (o.check) {
      var ck = !!o.check();
      r.classList.toggle("checked", ck);
      r.setAttribute("aria-checked", ck ? "true" : "false");
    }
    var n = o.on ? !!o.on() : false;
    r.classList.toggle("on", n);
    if (was !== null && n !== was) pop(r);
    was = n;
    if (o.sub) {
      var t = o.sub();
      sb.textContent = t || "";
      sb.style.display = t ? "" : "none";
    } else sb.style.display = "none";
    vl.textContent = r.classList.contains("slidable") ? _T("slide_to_unlock") : o.val ? o.val() : "";
  };
  reg(r.refresh);
  return r;
}

/* A CSS colour string as [r,g,b], so text can be chosen against it. */
function cssToRgb(s) {
  var e = document.createElement("span");
  e.style.color = s;
  e.style.display = "none";
  document.body.appendChild(e);
  var m = (getComputedStyle(e).color.match(/[\d.]+/g) || []).slice(0, 3).map(Number);
  e.remove();
  return m.length === 3 ? m : null;
}

function sliderRow(o) {
  var r = mk("div", "pill pane slide");
  r.innerHTML =
    "<div class='fill'></div>" +
    ic(o.icon) +
    "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='vl'></span>";
  r.querySelector(".nm").textContent = o.name;
  var fill = r.querySelector(".fill"),
    sb = r.querySelector(".sb"),
    vl = r.querySelector(".vl");
  var drag = false;
  /* While dragging, the thing the slider controls follows the finger: at most one update every 150 ms, and the last position always arrives. */
  var liveT = 0,
    liveAt = 0;
  function sendLive(v) {
    var wait = liveAt + 150 - Date.now();
    clearTimeout(liveT);
    if (wait <= 0) {
      liveAt = Date.now();
      o.live(v);
    } else
      liveT = setTimeout(function () {
        liveAt = Date.now();
        o.live(v);
      }, wait);
  }
  function snap(f) {
    var v = o.min + f * (o.max - o.min);
    var st = o.step || 1;
    v = Math.round((v - o.min) / st) * st + o.min;
    return Math.max(o.min, Math.min(o.max, Number(v.toFixed(2))));
  }
  function paint(v) {
    var f = (v - o.min) / (o.max - o.min);
    f = Math.max(0, Math.min(1, f));
    fill.style.width = f * 100 + "%";
    vl.textContent = o.fmt ? o.fmt(v) : v;
    if (o.fillColor) {
      var fc2 = o.fillColor();
      inkRow(r, fc2 ? cssToRgb(fc2) : null, f * 100);
    }
  }
  if (!o.readonly)
    attachSlide(r, {
      onMove: function (f) {
        drag = true;
        var v = snap(f);
        paint(v);
        if (o.live) sendLive(v);
      },
      onCommit: function (f) {
        var v = snap(f);
        clearTimeout(liveT);
        o.commit(v);
        setTimeout(function () {
          drag = false;
        }, 600);
      },
      onCancel: function () {
        drag = false;
      },
      onHold: o.onHold,
      onTap: function (t) {
        drag = false;
        if (o.onTap) o.onTap(t);
      },
    });
  else r.classList.add("static");
  r.refresh = function () {
    if (o.inert) r.classList.toggle("inert", !!o.inert());
    if (o.fillColor) {
