var MENU_ANCHOR = null;

/* The classes of a tick-several choice: " on" ticked, " ex" left out (when it has a third state). */
function multiClass(multi, o) {
  if (multi.state) return multi.state(o) === 1 ? " on" : multi.state(o) === 2 ? " ex" : "";
  return multi.on(o) ? " on" : "";
}

function openMenu(anchor, options, current, pick, fmt, multi) {
  closeMenu(true);
  var m = mk("div", "menu pane" + (multi ? " multi" : ""));
  options.forEach(function (o) {
    var it = mk("div", "mi" + (multi ? multiClass(multi, o) : String(o) === String(current) ? " on" : ""));
    if (multi) {
      var tx = mk("span", "mt");
      tx.textContent = fmt ? fmt(o) : cap(o);
      it.appendChild(tx);
      it.appendChild(mk("span", "ck", svg("check")));
      it.appendChild(mk("span", "xk", svg("close")));
    } else it.textContent = fmt ? fmt(o) : cap(o); /* an option comes from a device and is text, never markup */
    it.addEventListener("click", function (e) {
      e.stopPropagation();
      if (multi) {
        multi.toggle(o);
        m.querySelectorAll(".mi").forEach(function (el, i) {
          el.className = "mi" + multiClass(multi, options[i]);
        });
        return;
      }
      closeMenu();
      pick(o);
    });
    m.appendChild(it);
  });
  placeMenu(m, anchor);
}

/* A floating layer over the page, opened from `anchor`: as wide as it, starting at its edge, below it or above when there is no room. A tap away closes it. */
function placeMenu(m, anchor) {
  document.body.appendChild(m);
  /* The menu is as wide as the button it opens from and starts at its edge, measured at full size even when the button is shrunk by a press. */
  var r = anchor.getBoundingClientRect(),
    aw = anchor.offsetWidth,
    ax = r.left + (r.width - aw) / 2;
  m.style.width = aw + "px";
  var mh = m.offsetHeight,
    left = Math.max(8, Math.min(window.innerWidth - m.offsetWidth - 8, ax)),
    top = r.bottom + 6,
    up = false;
  if (top + mh > window.innerHeight - 8) {
    top = Math.max(8, r.top - mh - 6);
    up = true;
  }
  m.style.left = left + "px";
  m.style.top = top + "px";
  if (up) m.classList.add("up");
  m.style.setProperty(
    "--ox",
    Math.max(0, Math.min(100, ((ax + aw / 2 - left) / Math.max(1, m.offsetWidth)) * 100)) +
      "%"
  );
  anchor.classList.add("open");
  MENU_ANCHOR = anchor;
  MENU = m;
  setTimeout(function () {
    document.addEventListener("pointerdown", menuAway, true);
  }, 0);
}

function menuAway(e) {
  if (!MENU || MENU.contains(e.target)) return;
  var a = e.target.closest ? e.target.closest(".sel") : null;
  if (a && a === MENU_ANCHOR) {
    a._noopen = true;
    clearTimeout(a._noopenT);
    a._noopenT = setTimeout(function () {
      a._noopen = false;
    }, 2500);
  }
  closeMenu();
}

function closeMenu(instant) {
  document.removeEventListener("pointerdown", menuAway, true);
  if (MENU_ANCHOR) {
    MENU_ANCHOR.classList.remove("open");
    MENU_ANCHOR = null;
  }
  if (MENU) {
    var m = MENU;
    MENU = null;
    if (instant) m.remove();
    else {
      m.classList.add("out");
      setTimeout(function () {
        if (m !== MENU) m.remove();
      }, 170);
    }
  }
}

