}

function countOn(ids, okFn) {
  return ids.filter(function (id) {
    return okFn ? okFn(id) : V_(id) === "on";
  }).length;
}

function lightsLabel(ids) {
  return function () {
    var on = countOn(ids),
      miss = ids.filter(function (i) {
