function sv(id, unit, dp) {
  if (!svOk(id)) return "Offline";
  var v = Number(V_(id));
  return V_(id) === "" || !isFinite(v) ? "–" : v.toFixed(dp === undefined ? 1 : dp) + unit;
}

function svOk(id) {
  var s = V_(id);
  return s && s !== "unavailable" && s !== "unknown";
}

/* The key of a device made on this dashboard (an appliance, a remote): different even for two made in the same millisecond. */
function newKey(prefix) {
  return prefix + Date.now().toString(36).slice(-5) + Math.random().toString(36).slice(2, 7);
}

function imgOk(u) {
  return (
    typeof u === "string" &&
    ((u.length <= 300 && /^(https:\/\/|\/local\/)[^\s"'<>()\\]+$/.test(u)) ||
      (u.length <= 400000 && /^data:image\/jpeg;base64,[A-Za-z0-9+\/=]+$/.test(u)))
  );
}

function resizeImage(file, cb, maxDim, maxLen) {
  maxDim = maxDim || 1280;
  maxLen = maxLen || 380000;
  if (!file || file.type.indexOf("image/") !== 0) {
    cb(null);
    return;
  }
  var fr = new FileReader();
  fr.onload = function () {
    var im = new Image();
    im.onload = function () {
      var s = Math.min(1, maxDim / Math.max(im.width, im.height)),
        c = document.createElement("canvas");
      c.width = Math.max(1, Math.round(im.width * s));
      c.height = Math.max(1, Math.round(im.height * s));
      c.getContext("2d").drawImage(im, 0, 0, c.width, c.height);
      var q = 0.78,
        u = c.toDataURL("image/jpeg", q);
      while (u.length > maxLen && q > 0.3) {
        q -= 0.1;
        u = c.toDataURL("image/jpeg", q);
      }
      cb(u.length <= maxLen + 20000 ? u : null);
    };
    im.onerror = function () {
      cb(null);
    };
    im.src = fr.result;
  };
  fr.onerror = function () {
