  var out = [marks[0]],
    dir = 0;
  for (var q = 0; q + 1 < marks.length; q++) {
    var a = hsOf(marks[q]),
      b = hsOf(marks[q + 1]),
      ha = a[0],
      hb = b[0];
    if (a[1] < 3) ha = hb;
    if (b[1] < 3) hb = ha;
    var turn = (hb - ha + 360) % 360;
    if (!dir) dir = turn <= 180 ? 1 : -1;
    if (dir < 0 && turn > 0) turn -= 360;
    out.push(px(ha + turn / 2, (a[1] + b[1]) / 2), marks[q + 1]);
  }
  return out;
}

