var STOPS = {};

function stopStreams(o) {
  Object.keys(STOPS)
    .filter(function (k) {
      return !o || k === o || (o === "page" && k.indexOf("page") === 0);
    })
    .forEach(function (k) {
      if (STOPS[k]) {
        try {
          STOPS[k]();
        } catch (e) {}
        STOPS[k] = null;
      }
    });
}

function camFsExit(box) {
  var st = box._fs;
  if (!st) return;
  box._fs = null;
  box.classList.remove("fs");
  if (st.ph.parentNode) st.ph.parentNode.insertBefore(box, st.ph);
  else box.remove();
  st.ph.remove();
  var v = box.querySelector("video");
  if (v && v.srcObject) v.play().catch(function () {});
  var b = box.querySelector(".cbtns .rnd:last-child");
  if (b) b.innerHTML = svg("expand");
}

function camFull(box, vid, btn) {
  if (box._fs) {
    camFsExit(box);
    return;
  }
  function pseudo() {
    var ph = document.createComment("cam");
    box.parentNode.insertBefore(ph, box);
    box._fs = { ph: ph };
    document.body.appendChild(box);
    box.classList.add("fs");
    btn.innerHTML = svg("close");
    if (vid.srcObject) vid.play().catch(function () {});
  }
  function viaVideo() {
    if (vid.webkitEnterFullscreen && vid.readyState > 0) {
      try {
        vid.webkitEnterFullscreen();
        return;
      } catch (e) {}
    }
    pseudo();
  }
  var req = box.requestFullscreen || box.webkitRequestFullscreen;
  if (req && (document.fullscreenEnabled || document.webkitFullscreenEnabled)) {
    try {
      var p = req.call(box);
      if (p && p.catch) p.catch(viaVideo);
    } catch (e) {
      viaVideo();
    }
    return;
  }
  viaVideo();
}

/* opts (all optional): onMute(button) takes over the mute button, for a popup whose sound is not the video's (a door call's audio comes from its own channel; the button is kept as box._mu so the popup can show its state); noFullscreen leaves out the full screen button. */
function stream(box, id, owner, tapOpen, noIntercom, opts) {
  opts = opts || {};
  stopStreams(owner);
  /* The snapshot sits behind the video, which stays transparent until the live picture is really showing, so a stream that connects black never replaces it. */
  var tok = A(id).access_token,
    snap = null;
  if (tok) {
    snap = mk("img", "snap");
    snap.alt = "";
    snap.src = HA.camera.snapshotUrl(id, tok);
    box.appendChild(snap);
  }
  var vid = mk("video");
  vid.muted = true;
  vid.autoplay = true;
  vid.playsInline = true;
  vid.setAttribute("playsinline", "");
  box.appendChild(vid);
  var bt = mk("div", "cbtns");
  var mu = mk("div", "rnd pane", svg("mute")),
    fs = mk("div", "rnd pane", svg("expand"));
  mu.addEventListener("click", function (e) {
    e.stopPropagation();
    if (opts.onMute) {
      opts.onMute(mu);
      return;
    }
    vid.muted = !vid.muted;
    mu.innerHTML = svg(vid.muted ? "mute" : "volup");
  });
  if (opts.onMute) {
    mu.setAttribute("role", "button");
    mu.setAttribute("aria-label", _T("dc_speaker"));
  }
  box._mu = mu;
  fs.addEventListener("click", function (e) {
    e.stopPropagation();
    camFull(box, vid, fs);
  });
  bt.appendChild(mu);
  if (!opts.noFullscreen) bt.appendChild(fs);
  camTalkButton(box, id, bt);
  box.appendChild(bt);
  if (!noIntercom) camIntercom(box, id);
  if (tapOpen)
    box.addEventListener("click", function () {
      if (!box._fs) showPopup(tapOpen === true ? "camera" : tapOpen, true);
    });
  /* A picture that is slow to come (a building's camera) shows a spinner in the middle until a picture is showing (the snapshot behind the video, or the first decoded frame of the video), and says so when it takes long, so a camera that has given up looks different from one that is still on its way. It goes with the first decoded frame, not with the player's own checks (which also wait for movement and a bright enough picture, and can take seconds more). */
  var spin = mk("div", "camspin", "<i></i><span></span>"),
    late = setTimeout(function () {
      spin.classList.add("late");
      spin.querySelector("span").textContent = _T("cam_still_connecting");
    }, 12000);
  box.appendChild(spin);
  function spinSync() {
    var pic = (vid.readyState >= 2 && vid.videoWidth > 0) || !!(snap && snap.complete && snap.naturalWidth > 0);
    spin.style.display = pic ? "none" : "";
    if (pic) {
      clearTimeout(late);
      spin.classList.remove("late");
    }
  }
  var spinEvents = ["loadeddata", "playing", "canplay", "resize", "emptied", "loadstart"];
  spinEvents.forEach(function (ev) {
    vid.addEventListener(ev, spinSync);
  });
  /* The snapshot behind the video is a picture too: it ends the wait as soon as it has loaded. */
  if (snap) snap.addEventListener("load", spinSync);
  spinSync();
  var stop = window.CameraStream.start(vid, id);
  STOPS[owner] = function () {
    clearTimeout(late);
    spinEvents.forEach(function (ev) {
      vid.removeEventListener(ev, spinSync);
    });
    if (snap) snap.removeEventListener("load", spinSync);
    camFsExit(box);
    stop();
    vid.removeAttribute("src");
    vid.srcObject = null;
  };
}

