        else
          confirmDlg(_T("sound_the_siren_now"), function () {
            call("siren", "turn_on", { entity_id: eid });
          });
      },
    });
  return pill(dm === "light" ? "bright" : "power", nm, {
    on: function () {
      return isOn(eid);
    },
    sub: function () {
      return gone() ? _T("unavailable") : stAgo(eid);
    },
    tap: function () {
      call(dm, "toggle", { entity_id: eid });
    },
  });
}

function advPopup(b, id) {
