    if (dm === "binary_sensor") {
      if (ALERT_BIN.indexOf(dc) >= 0) out.problems.push({ id: eid, bin: true });
      else if (STATE_BIN.indexOf(dc) >= 0 && !en.entity_category) out.read.push(eid);
      return;
    }
    if (dm !== "sensor") return;
    if (/(^|_)(fault|error)s?(_|$)/.test(k)) {
