/* Show rules: a section can appear only while an entity is (or is not) in a given state. While editing it always shows, marked. */
var RULEDOMS = [
  "light",
  "switch",
  "input_boolean",
  "binary_sensor",
  "sensor",
  "person",
  "device_tracker",
  "media_player",
  "climate",
