        },
      });
      rows.push(r);
      box.appendChild(r);
    });
    makeSortable(box, rows, function (from, to) {
      var a = secOrder(sc),
        x = a.splice(from, 1)[0];
      a.splice(to, 0, x);
      setSecOrder(sc, a);
      uiChanged();
      setTimeout(draw, 250);
    });
