/* ---- per-user appearance ---- */
var PREFS = {
  theme: "dark",
  wall: false,
  wallIdle: 120,
  wallMode: "clock",
  wallDim: true,
  pinHdr: true,
  hdrSize: "",
  startView: "",
  accH: 174,
  tf: "auto",
};

function mergePrefs(v) {
  if (!v || typeof v !== "object") return;
  if (v.theme === "dark" || v.theme === "light" || v.theme === "auto") PREFS.theme = v.theme;
  ["wall", "wallDim", "pinHdr"].forEach(function (k) {
    if (typeof v[k] === "boolean") PREFS[k] = v[k];
  });
  if (typeof v.wallIdle === "number" && v.wallIdle >= 30 && v.wallIdle <= 3600)
    PREFS.wallIdle = Math.round(v.wallIdle);
  if (v.wallMode === "clock" || v.wallMode === "photo") PREFS.wallMode = v.wallMode;
  if (typeof v.startView === "string" && /^[a-z0-9_-]{0,24}$/.test(v.startView))
    PREFS.startView = v.startView;
  if (v.tf === "auto" || v.tf === "12" || v.tf === "24") PREFS.tf = v.tf;
  if (v.hdrSize === "regular" || v.hdrSize === "slim" || v.hdrSize === "") PREFS.hdrSize = v.hdrSize;
  if (typeof v.accH === "number" && v.accH >= 0 && v.accH < 360) PREFS.accH = Math.round(v.accH);
}

function savePrefsLocal() {
  deviceSet("db_prefs", PREFS);
}

function themeLight() {
  return (
    PREFS.theme === "light" ||
    (PREFS.theme === "auto" &&
      !!window.matchMedia &&
      window.matchMedia("(prefers-color-scheme: light)").matches)
  );
}

/* One steady accent colour that the user picks. */
function flatAccent() {
  var c = hsl2rgb(PREFS.accH, 0.82, themeLight() ? 0.46 : 0.62);
  return "rgb(" + Math.round(c[0]) + "," + Math.round(c[1]) + "," + Math.round(c[2]) + ")";
}

function applyTheme() {
  var c = document.body.classList;
  c.toggle("light", themeLight());
  c.toggle("pinhdr", PREFS.pinHdr !== false);
  document.documentElement.style.setProperty("--acc", flatAccent());
  wallApply();
}

function initTheme() {
  try {
    window.matchMedia("(prefers-color-scheme: light)").addEventListener("change", function () {
      if (PREFS.theme === "auto") applyTheme();
    });
  } catch (e) {}
  var device = deviceGet("db_prefs", null);
  mergePrefs(device);
  applyTheme();
  /* This person's choices as saved in Home Assistant (this device's copy is already in). When this device has a copy the page does not wait for them: they are taken over when they arrive.
     With no copy (the first visit) the page waits until they are in, or cannot be read. */
  var saved = HA.data
    .get("user", "dashboard_prefs")
    .then(function (v) {
      if (v) {
        mergePrefs(v);
        applyTheme();
      }
      /* Kept even when Home Assistant has nothing saved, so the next visit knows this device has read them and does not wait. */
      savePrefsLocal();
    })
    .catch(function () {});
  return device ? Promise.resolve() : saved;
}

/* The page the dashboard opens on: the one chosen in Start on, unless the address names a page. Once, when the page is first drawn. */
function startViewApply() {
  var want = PREFS.startView;
  if (VIEW === "home" && want && ORDER.indexOf(want) >= 0) VIEW = want;
}

function setPref(k, v) {
  PREFS[k] = v;
  savePrefsLocal();
  applyTheme();
  var h = H();
  if (h)
    HA.data.set("user", "dashboard_prefs", PREFS).catch(function () {
      toast(_T("couldn_t_save_your_appearance_choice"));
    });
}

