var EA_DUMMIES = [
  ["tv", "tv", "tv"],
  ["sofa", "sofa", "sofa"],
  ["bed", "bed", "bed"],
  ["rug", "rug", "rug"],
  ["speaker", "speaker", "speaker"],
  ["door", "door", "leave"],
  ["window", "window", "bright"],
  ["other", "other", "plug"],
