/* Where the next light is put when it is added: spread over the room so none hides another. */
var EA_SLOTS = [
  [-0.6, -0.5],
  [0.6, -0.5],
  [-0.6, 0.5],
  [0.6, 0.5],
  [0, -0.7],
  [0, 0.7],
  [-0.7, 0],
  [0.7, 0],
