  eaSvg("polygon", { class: "ae-wr", points: eaPts([T, R, up(R), up(T)]) }, root);
  eaSvg("polygon", { class: "ae-fl", points: eaPts([T, R, B, L]) }, root);
  eaSvg("polyline", { class: "ae-ed", points: eaPts([L, T, R]) }, root);
