var DAYLAB = [_T("mon"), _T("tue"), _T("wed"), _T("thu"), _T("fri"), _T("sat"), _T("sun")];

/* ---- Conditions: shared by the section visibility rules ---- */
var HHMM = /^([01]\d|2[0-3]):[0-5]\d$/,
