          action: "climate.set_temperature",
          target: { entity_id: a.id },
          data: { hvac_mode: a.mode, temperature: a.temp || 24 },
        });
      else acts.push({ action: "climate.turn_off", target: { entity_id: a.id } });
    } else
      acts.push({
        action: dm + "." + (a.on === false ? "turn_off" : "turn_on"),
        target: { entity_id: a.id },
      });
  });
  return acts;
}

