function dslotSet(d, path, v) {
  var p = path.split(".");
  if (p.length === 1) {
    if (v === undefined) delete d[p[0]];
    else d[p[0]] = v;
    return;
  }
  d[p[0]] = d[p[0]] || {};
  if (v === undefined) delete d[p[0]][p[1]];
  else d[p[0]][p[1]] = v;
