  var zones = zoneLightIds(h.states, h.entities);
  return (REG || [])
    .filter(function (e) {
      return (
        NEWDOMS.test(e.entity_id) &&
        !zones[e.entity_id] &&
        !e.entity_category &&
        !e.hidden_by &&
        !e.disabled_by &&
        h.states[e.entity_id] &&
